DO $$ BEGIN IF EXISTS(SELECT 1 FROM opportunity_catalog.opportunity LIMIT 1) THEN RAISE EXCEPTION 'F12_ROLLBACK_REQUIRES_EMPTY_SCHEMA'; END IF; END $$;
REVOKE SELECT(organization_id,document_id,version_id,state,scan_state,lock_version) ON document_storage.document_version FROM c4g_opportunity_tenant_runtime;
REVOKE USAGE ON SCHEMA document_storage FROM c4g_opportunity_tenant_runtime;
REVOKE REFERENCES (organization_id,document_id,version_id) ON document_storage.document_version FROM c4g_opportunity_tenant_owner;
REVOKE USAGE ON SCHEMA document_storage FROM c4g_opportunity_tenant_owner;
